import{_ as r,a0 as n,w as o,s as l,I as e,x as a,a1 as s,A as d,ao as u}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const D=JSON.parse('{"title":"如何在 Ubuntu 上使用 ADB 備份 Android 數據 | LCTT x X-CMD","titleTemplate":false,"description":"如何在 Ubuntu 上使用 ADB 備份 Android 數據 | LCTT (201702) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在 Ubuntu 上使用 ADB 備份 Android 數據 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 Ubuntu 上使用 ADB 備份 Android 數據 | LCTT (201702) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201702/20170213 How to Back Up Your Android Data with ADB on Ubuntu","title":"如何在 Ubuntu 上使用 ADB 備份 Android 數據","tag":"201702","desc":""},"relativePath":"201702/20170213 How to Back Up Your Android Data with ADB on Ubuntu.md","filePath":"[post].md"}'),p={name:"201702/20170213 How to Back Up Your Android Data with ADB on Ubuntu.md"};function b(h,t,g,k,m,A){const i=n("Link");return o(),l("div",null,[t[16]||(t[16]=e("h1",{id:"如何在-ubuntu-上使用-adb-備份-android-數據",tabindex:"-1"},[a("如何在 Ubuntu 上使用 ADB 備份 Android 數據 "),e("a",{class:"header-anchor",href:"#如何在-ubuntu-上使用-adb-備份-android-數據","aria-label":"Permalink to “如何在 Ubuntu 上使用 ADB 備份 Android 數據”"},"​")],-1)),t[17]||(t[17]=e("p",null,[e("img",{src:"https://maketecheasier-2d0f.kxcdn.com/assets/uploads/2017/02/android-backup-ubuntu.jpg",alt:"",title:"How to Back Up Your Android Data with ADB on Ubuntus"})],-1)),t[18]||(t[18]=e("p",null,"備份 Android 系統上的應用數據、文本信息等等是非常乏味的，有時還很昂貴。電子市場的許多應用都承諾可以備份數據，但效果不佳或者需要付昂貴費用。你是否知道有一種更好的方法可以來做這件事，並且在你的電腦上就可以完成？",-1)),t[19]||(t[19]=e("p",null,[a("Android 自帶一套開發工具。有許多種開發工具，但人們最為感興趣的項目是 ADB（或者叫做 "),e("ruby",null,[a("Android 調試橋"),e("rt",null," Android Debug Bridge")]),a("）。它允許用户通過命令列直接訪問任何 Android 設備。有了這個工具，一切皆有可能 - 包括備份整個 Android 設備。在這篇文章中，將討論如何在 Ubuntu 系統上完成這件事。")],-1)),e("p",null,[t[1]||(t[1]=e("strong",null,"注",-1)),t[2]||(t[2]=a("：這篇教程是針對 Ubuntu Linux 系統的。不過， ADB 在 Windows 系統和 Mac 上也是可用的，也可以在這些平台上對 Android 數據進行備份。",-1)),s(i,{href:"https://developer.android.com/studio/command-line/adb.html"},{default:d(()=>[...t[0]||(t[0]=[a("下載針對 Windows 和 Mac 的 ADB 版本。",-1)])]),_:1})]),t[20]||(t[20]=u('<h3 id="安裝-adb-並啓用-usb-調試" tabindex="-1">安裝 ADB 並啓用 USB 調試 <a class="header-anchor" href="#安裝-adb-並啓用-usb-調試" aria-label="Permalink to “安裝 ADB 並啓用 USB 調試”">​</a></h3><p>打開一個終端窗口，然後輸入下面的命令來安裝 ADB，它將與 Android 進行會話。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt install adb</span></span></code></pre></div><p><img src="https://maketecheasier-2d0f.kxcdn.com/assets/uploads/2017/02/adb-install-adb-ubuntu.jpg" alt="adb-install-adb-ubuntu" title="adb-install-adb-ubuntu"></p><p>在系統上安裝好 ADB 工具以後，需要在 Android 內部啓動調試。首先打開 Android 的<ruby>設置<rt>Settings</rt></ruby>區域。然後一直滾動到底部找到“<ruby>關於手機<rt>About Phone</rt></ruby>”並點擊。這將打開“<ruby>電話狀態<rt>Phone status</rt></ruby>”頁。在這一頁面上再次滾動到底部，找到“<ruby>版本號<rt>Build number</rt></ruby>”並點擊七次，從而啓動開發者模式。</p><p><img src="https://maketecheasier-2d0f.kxcdn.com/assets/uploads/2017/02/adb-about-phone.jpg" alt="adb-about-phone" title="adb-about-phone"></p><p>為了進入<ruby>開發者設置<rt>Developer Settings</rt></ruby>，按設備上的返回鍵返回上一頁面。在“設置”中將會出現一個新的選項：“<ruby>開發者選項<rt>Developer options</rt></ruby>”。點擊它進入開發者設置區域。滾動頁面直到看到 “<ruby>Android 調試<rt>Android debugging</rt></ruby>”（或它的一些其他名稱），點擊它啓用設置。</p><h3 id="備份" tabindex="-1">備份 <a class="header-anchor" href="#備份" aria-label="Permalink to “備份”">​</a></h3><p>使用 ADB 創建一個備份就如同運行一個命令一樣簡單。首先，用一根與 Android 設備匹配的 USB 線將 Android 設備連接到電腦上。然後打開終端運行下面的命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>adb start-server</span></span></code></pre></div><p>這將啓動 ADB 服務器。運行這個命令時，要快速解鎖 Android 設備，因為 ADB 將強制出現一個確認窗口，必須選擇接受後才可繼續。</p><p><img src="https://maketecheasier-2d0f.kxcdn.com/assets/uploads/2017/02/adb-all-usb-debugging.jpg" alt="adb-all-usb-debugging" title="adb-all-usb-debugging"></p><p>要啓動備份進程，打開終端，然後執行下面的備份命令。該命令將讀取 Android 上的文本信息以及其他應用數據，然後存入加密文件中。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>adb backup -apk -shared -all -f backup-file.adb</span></span></code></pre></div><p><img src="https://maketecheasier-2d0f.kxcdn.com/assets/uploads/2017/02/adb-full-backup.jpg" alt="adb-full-backup" title="adb-full-backup"></p><p>當運行備份命令時，Android 會在啓動備份進程前提示用户查看 Android 並設置加密文件的密碼。請輸入一個強壯而容易記住的密碼。然後，點擊“備份我的數據”按鈕。備份過程將會花費一定時間。備份完成以後，在目錄 <code>/home/username/</code> 中會出現一個叫做 <code>backup-file.adb</code> 的文件。</p><h3 id="恢復備份" tabindex="-1">恢復備份 <a class="header-anchor" href="#恢復備份" aria-label="Permalink to “恢復備份”">​</a></h3><p>要恢復備份，首先啓用 ADB 服務器（像上面提到的一樣），然後運行下面這個命令來還原備份數據：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>adb restore backup-file.adb</span></span></code></pre></div><p><img src="https://maketecheasier-2d0f.kxcdn.com/assets/uploads/2017/02/adb-full-restore.jpg" alt="adb-full-restore" title="adb-full-restore"></p><p>再次轉到 Android， 因為 ADB 將提示用户輸入密碼。這次，不是創建一個密碼，而是需要輸入之前創建的那個密碼。在點擊 “<ruby>恢復我的數據<rt>restore my data</rt></ruby>” 以後，恢復進程就開始了。耐心點，因為這可能需要一定時間。</p><h3 id="結論" tabindex="-1">結論 <a class="header-anchor" href="#結論" aria-label="Permalink to “結論”">​</a></h3><p>沒有多少 Android 用户知道這樣備份數據，但是 ADB 的確很強大。利用它甚至可以獲得對設備的 root 訪問。事實上，利用這個工具還可以做很多的事情，需要更多的文章來討論它。</p><p>你還知道 ADB 可以用來幹什麼嗎？請在下面的評論區告知我們！</p><hr>',25)),e("p",null,[t[4]||(t[4]=a("via: ",-1)),s(i,{href:"https://www.maketecheasier.com/back-up-android-data-adb-ubuntu/"},{default:d(()=>[...t[3]||(t[3]=[a("https://www.maketecheasier.com/back-up-android-data-adb-ubuntu/",-1)])]),_:1})]),e("p",null,[t[8]||(t[8]=a("作者：",-1)),s(i,{href:"https://www.maketecheasier.com/author/derrikdiener/"},{default:d(()=>[...t[5]||(t[5]=[a("Derrik Diener",-1)])]),_:1}),t[9]||(t[9]=a(" 譯者：",-1)),s(i,{href:"https://github.com/ucasFL"},{default:d(()=>[...t[6]||(t[6]=[a("ucasFL",-1)])]),_:1}),t[10]||(t[10]=a(" 校對：",-1)),s(i,{href:"https://github.com/jasminepeng"},{default:d(()=>[...t[7]||(t[7]=[a("jasminepeng",-1)])]),_:1})]),e("p",null,[t[13]||(t[13]=a("本文由 ",-1)),s(i,{href:"https://github.com/LCTT/TranslateProject"},{default:d(()=>[...t[11]||(t[11]=[a("LCTT",-1)])]),_:1}),t[14]||(t[14]=a(" 原創編譯，",-1)),s(i,{href:"https://linux.cn/"},{default:d(()=>[...t[12]||(t[12]=[a("Linux中國",-1)])]),_:1}),t[15]||(t[15]=a(" 榮譽推出",-1))])])}const B=r(p,[["render",b]]);export{D as __pageData,B as default};
